function smallestBySwaps(nums: number[], limit: number): number[] {
  const n = nums.length;
  const parent = nums.map((_, i) => i);
  const find = (x: number): number => (parent[x] === x ? x : (parent[x] = find(parent[x])));
  for (let i = 0; i < n; i++)
    for (let j = i + 1; j < n; j++)
      if (Math.abs(nums[i] - nums[j]) <= limit) parent[find(i)] = find(j);
  const groups = new Map<number, number[]>();
  for (let i = 0; i < n; i++) {
    const g = find(i);
    if (!groups.has(g)) groups.set(g, []);
    groups.get(g)!.push(i); // indexes come out ascending
  }
  const out = nums.slice();
  for (const idx of groups.values()) {
    const vals = idx.map(i => nums[i]).sort((a, b) => a - b);
    idx.forEach((pos, k) => (out[pos] = vals[k]));
  }
  return out;
}

