function smallestBySwaps(nums: number[], limit: number): number[] {
  const n = nums.length;
  const order = nums.map((_, i) => i).sort((a, b) => nums[a] - nums[b]);
  const out = new Array(n);
  let start = 0;
  for (let i = 1; i <= n; i++) {
    if (i === n || nums[order[i]] - nums[order[i - 1]] > limit) {
      // order[start..i-1] is one group; its values are already ascending
      const pos = order.slice(start, i).sort((a, b) => a - b);
      for (let k = 0; k < pos.length; k++) out[pos[k]] = nums[order[start + k]];
      start = i;
    }
  }
  return out;
}

