    def smallestBySwaps(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        order = sorted(range(n), key=lambda i: nums[i])
        out = [0] * n
        start = 0
        for i in range(1, n + 1):
            if i == n or nums[order[i]] - nums[order[i - 1]] > limit:
                pos = sorted(order[start:i])
                for k, p in enumerate(pos):
                    out[p] = nums[order[start + k]]
                start = i
        return out

